from modele import *

def A(i,t,e,c,m,k,fig=None):
    return E(t,e,c,m,k,figure=fig if fig is not None else f'script-{i:02}')

chapitre(17,'algorithmique','Algorithmique, blocs et tableur','5 · Algorithmique et raisonnement',
'Variables · Conditions · Boucles · Blocs personnalisés · Projets',
['Lire, compléter et construire un script par blocs.','Utiliser variables, tests et boucles.','Organiser un projet avec des événements et plusieurs lutins.'],['Calcul numérique et repérage.'],[
r'''\essSection{1}{Lire et écrire un algorithme}
\begin{definition}Un algorithme est une suite d’instructions précises. Une variable mémorise une valeur que l’on peut modifier. « Mettre x à 3 » remplace son contenu ; « ajouter 3 à x » augmente sa valeur actuelle. Une entrée peut provenir d’une réponse de l’utilisateur.\end{definition}
\begin{definition}Une condition choisit un traitement selon un test vrai ou faux. Une boucle « répéter n fois » exécute son contenu n fois. Une boucle « répéter jusqu’à » s’arrête quand son test devient vrai ; elle peut ne jamais finir si le contenu ne permet pas de l’atteindre.\end{definition}
\begin{savoirfaire}[Exécuter à la main]Préparer un tableau avec une colonne par variable et une ligne par étape ou tour. Exécuter dans l’ordre, en utilisant les valeurs déjà modifiées. Distinguer les instructions dans la boucle de celles placées après.\end{savoirfaire}
\begin{attention}Les blocs du livre représentent les opérations de type Scratch. Les lignes indentées sont à l’intérieur du bloc ; une ligne « fin » le ferme. Les multiplications sont explicites. Un test n’est pas une affectation.\end{attention}''',
r'''\essSection{2}{Décomposer, simuler et interagir}
\begin{definition}Un bloc personnalisé regroupe des instructions réutilisables ; un paramètre lui fournit une valeur. Pour dessiner un carré de côté c, répéter quatre fois « avancer de c ; tourner de 90 degrés ».\end{definition}
\begin{savoirfaire}[Simuler]Choisir un entier aléatoire de 1 à 6 modélise un dé équilibré si chaque entier est équiprobable. Répéter les tirages, compter les succès et diviser par le nombre d’essais. Initialiser le compteur à zéro avant la boucle.\end{savoirfaire}
\begin{definition}Plusieurs scripts peuvent fonctionner en parallèle sur plusieurs lutins. Un événement, comme un clic, une touche ou un message, démarre un script. Un message peut coordonner les lutins ; son envoi avec attente permet d’attendre la fin des traitements qu’il déclenche.\end{definition}
\begin{savoirfaire}[Tableur]Une formule commence par =. Dans =A2*3+1, la référence A2 devient A3 lors d’une recopie vers le bas. Une référence absolue comme \$B\$1 reste fixe. Contrôler les premières et dernières lignes après recopie.\end{savoirfaire}'''],[
A(1,'Suivre trois opérations',r"Exécuter le script et donner la valeur affichée.",r"x prend successivement 3, 8 et 16. Le bloc dire affiche $\res{16}$. Ajouter puis multiplier ne donne pas le même résultat que multiplier puis ajouter.","Écrire chaque valeur dans l’ordre.","assert (3+5)*2==16"),
A(2,'Un nombre demandé',r"Le script lit un nombre x. Donner le résultat pour 2 et pour $-4$, puis l’expression obtenue à partir de x.",r"Après ajout, on a $x+4$ ; après multiplication, $3(x+4)$. Les résultats sont $\res{18}$ et $\res0$. Les parenthèses traduisent l’ordre des blocs.","Traduire les modifications successives.","assert 3*(2+4)==18 and 3*(-4+4)==0"),
A(3,'Une boucle bornée',r"Quelle valeur affiche le script ? Combien de fois le bloc ajouter est-il exécuté ?",r"Le bloc ajouter s’exécute quatre fois. Les valeurs sont 3, 6, 9, 12. La sortie est $\res{12}$. Le bloc dire placé après la boucle s’exécute une seule fois.","Repérer les limites de la boucle.","assert sum([3]*4)==12"),
A(4,'Un test et deux branches',r"Exécuter le script pour les entrées 9, 10 et 14.",r"Le test est $x\ge10$, donc il est faux pour 9 et vrai pour 10 et 14. Les sorties sont respectivement $\res{\text{petit, grand, grand}}$. La borne 10 appartient bien à la première branche du test vrai.","Tester la valeur située à la frontière.","assert [a>=10 for a in [9,10,14]]==[False,True,True]"),
A(5,'Doubler plusieurs fois',r"Quelle est la valeur finale de x ? Un élève propose $2+3\times2$. Expliquer son erreur.",r"Les trois tours donnent 4, 8, 16. La sortie est $\res{16=2\times2^3}$. Le script multiplie à chaque tour ; il n’ajoute pas 2 trois fois.","Distinguer additions et multiplications répétées.","assert 2*2**3==16 and 2+3*2!=16"),
A(6,'Une somme cumulée',r"Suivre les variables s et n à chaque tour puis donner le résultat.",r"Au départ $(s;n)=(0;1)$. Après les cinq tours : $(1;2),(3;3),(6;4),(10;5),(15;6)$. La sortie est $\res{15}$. L’ajout à s précède l’augmentation de n.","Faire un tableau des deux variables.","assert sum(range(1,6))==15"),
A(7,'Répéter jusqu’à',r"Donner les valeurs successives de x et le nombre de tours.",r"En partant de 0, on obtient 6, 12, 18 puis 24. Le test $x\ge20$ devient vrai à 24 : $\res{4\text{ tours}}$ et sortie $\res{24}$. La boucle ne s’arrête pas à 20, qui n’est jamais atteint.","Vérifier le test avant chaque nouveau tour.","assert [6*i for i in range(5)]==[0,6,12,18,24]"),
A(8,'Un carré',r"Le stylo est baissé, le lutin part de (0;0), dirigé vers la droite. Décrire le tracé ; les rotations se font dans le sens inverse des aiguilles d’une montre.",r"Quatre segments de 40 unités et quatre quarts de tour forment un carré. Les sommets sont $(0;0),(40;0),(40;40),(0;40)$ puis retour au départ. Le périmètre est $\res{160}$ unités.","Suivre position et orientation.","assert 4*40==160"),
A(9,'Tester un multiple',r"Le symbole « mod » désigne le reste de la division entière. Que renvoie le script pour 18 et 19 ? Que reconnaît-il ?",r"$18\bmod3=0$ : sortie $\res1$. $19\bmod3=1$ : sortie $\res0$. Pour une entrée entière, il reconnaît les multiples de 3. Le compteur y est initialisé avant le test.","Relier reste nul et divisibilité.","assert 18%3==0 and 19%3==1"),
A(10,'Énumérer des diviseurs',r"Quelles valeurs sont affichées ? Pourquoi commence-t-on d à 1 et non à 0 ?",r"Le script teste d de 1 à 12 et affiche $\res{1,2,3,4,6,12}$. Ce sont tous les diviseurs positifs de 12. Commencer par 0 rendrait le calcul du reste impossible, car on ne divise pas par zéro.","Comprendre l’intervalle parcouru par la boucle.","assert [d for d in range(1,13) if 12%d==0]==[1,2,3,4,6,12]"),
A(11,'Une boucle qui dépasse',r"Combien de tours effectue le script ? Remplacer « multiplier par 2 » par « ajouter 0 » permettrait-il encore de terminer ?",r"Les valeurs sont 1, 2, 4, 8, 16, 32, 64. Il faut $\res6$ tours avant $x>50$. Avec « ajouter 0 », x reste 1 ; le test ne devient jamais vrai et la boucle ne termine pas.","Prouver que la variable progresse vers la condition d’arrêt.","assert 2**5<=50<2**6"),
A(12,'Un bloc personnalisé',r"Le bloc carré(c) trace un carré et revient au même point avec la même orientation. Compléter le projet pour dessiner trois carrés de côté 30, dont les sommets de départ sont espacés de 40 unités horizontalement.",r"Répéter trois fois : carré(30), relever le stylo, avancer de 40, baisser le stylo. Le déplacement n’est pas dans le bloc carré, sinon il déplacerait aussi les coins. Les départs sont 0, 40, 80 ; le dernier déplacement porte le lutin à 120 sans tracer.","Séparer le motif et le déplacement entre motifs.","assert [40*i for i in range(3)]==[0,40,80]",fig='script-carres'),
A(13,'Simuler un dé',r"Compléter le projet pour compter les six sur 600 lancers. Où placer l’initialisation et le calcul de fréquence ?",r"Mettre succès à 0 avant la boucle. Répéter 600 fois : choisir un entier aléatoire de 1 à 6 ; si le résultat vaut 6, ajouter 1 à succès. Après la boucle, afficher succès/600. La probabilité théorique est $1/6$ ; on ne promet pas exactement 100 succès.","Initialiser une fois, compter à chaque tour, diviser à la fin.","assert Rational(100,600)==Rational(1,6)",fig='script-simulation'),
A(14,'Deux lutins coordonnés',r"Le lutin Guide, au clic sur le drapeau, met score à 0 puis envoie « départ » et attend. Le lutin Joueur, à réception de « départ », ajoute 1 au score dix fois. Guide affiche ensuite score. Quel résultat ? Pourquoi utiliser l’envoi avec attente ?",r"Le compteur atteint $\res{10}$. L’attente garantit que le script déclenché chez Joueur est terminé avant l’affichage. Sans attente, les deux scripts continueraient en parallèle et l’affichage pourrait survenir avant la fin du comptage. Les blocs de deux lutins ne forment pas une seule pile.","Identifier l’événement et la synchronisation.","score=0\nfor _ in range(10): score+=1\nassert score==10",fig='script-parallele'),
A(15,'Un tableur recopié',r"En A2:A6 figurent 0, 1, 2, 3, 4. B1 contient 5. On saisit en B2 =3*A2+\$B\$1, puis recopie jusqu’à B6. Donner les résultats et la dernière formule.",r"Les résultats sont $\res{5,8,11,14,17}$. La dernière formule est =3*A6+\$B\$1. La référence de la ligne A se déplace ; la cellule du terme constant reste fixée. Sans les dollars, B1 se déplacerait à tort.","Suivre séparément références relatives et absolues.","assert [3*a+5 for a in range(5)]==[5,8,11,14,17]",fig='script-tableur')
],reperes=['Variables, tests et exécution à la main','Boucles bornées et conditionnelles','Blocs, simulation et scripts parallèles','Formules de tableur et recopie'],deco='algorithmique')

chapitre(18,'raisonner','Raisonner et préparer le brevet','5 · Algorithmique et raisonnement',
'Conjecturer · Démontrer · Chercher · Rédiger · Vérifier',
['Construire une démarche dans un problème ouvert.','Distinguer exemple, preuve et contre-exemple.','Organiser le temps et la rédaction du brevet.'],['Ensemble des chapitres précédents.'],[
r'''\essSection{1}{De l’essai à la preuve}
\begin{definition}Une conjecture est une affirmation que l’on pense vraie après des observations. Une preuve établit une conclusion à partir d’hypothèses et de propriétés. Un seul contre-exemple suffit à réfuter une affirmation universelle ; plusieurs exemples ne suffisent pas à la démontrer.\end{definition}
\begin{savoirfaire}[Chercher]Reformuler la question, lister les données, choisir une représentation, essayer un cas simple. Conserver les essais utiles. Une question précédente peut fournir une longueur, une expression ou une idée réutilisable.\end{savoirfaire}
\begin{savoirfaire}[Démontrer]Pour une propriété de nombres entiers, traduire « pair » par $2n$, « impair » par $2n+1$ et « multiple de d » par $dn$. En géométrie, écrire les hypothèses avant le théorème et nommer les objets dans la conclusion.\end{savoirfaire}
\begin{attention}Une image de calculatrice, une mesure sur le dessin ou un essai de programme donne une observation ; cela ne justifie pas à soi seul une propriété pour tous les cas.\end{attention}''',
r'''\essSection{2}{Une copie claire dans le temps imparti}
\begin{savoirfaire}[Brevet 2027]Selon le texte officiel de septembre 2026, l’épreuve dure 2 h : 20 min d’automatismes et applications directes sur 6 points, sans calculatrice ; puis 1 h 40 de raisonnement et résolution de problèmes sur 14 points, avec calculatrice autorisée. La première copie est rendue après 20 minutes.\end{savoirfaire}
\begin{propriete}Les réponses de la première partie sont courtes. La seconde partie ne comporte pas de QCM. La qualité de l’expression et de la rédaction est évaluée sur 2 points compris dans la note sur 20. Les brevets blancs du livre reprennent cette organisation avec un barème pédagogique propre.\end{propriete}
\begin{savoirfaire}[Rédiger]Écrire le calcul ou la propriété utile, donner les étapes essentielles, indiquer unités et arrondis, puis répondre par une phrase. Si un résultat intermédiaire manque, poursuivre avec une valeur annoncée ou une démarche explicitée quand c’est possible.\end{savoirfaire}
\begin{savoirfaire}[Vérifier]Relire les nombres copiés, le signe, la précision, les unités, les domaines et les ordres de grandeur. Une probabilité ne dépasse pas 1 ; une aire reste positive ; un achat entier se majore pour couvrir un besoin.\end{savoirfaire}'''],[
E('Un contre-exemple',r"« Le carré d’un nombre est toujours plus grand que ce nombre. » Réfuter cette phrase.",r"Avec $x=1/2$, $x^2=1/4<1/2$. Ce seul contre-exemple suffit. Avec 0 ou 1, l’inégalité stricte serait également fausse par égalité.","Chercher un cas qui contredit exactement l’affirmation.","assert Rational(1,2)**2<Rational(1,2)"),
E('Deux entiers impairs',r"Démontrer que la somme de deux entiers impairs est paire.",r"Écrivons les deux impairs $2a+1$ et $2b+1$, avec a, b entiers. Leur somme vaut $2(a+b+1)$, donc c’est un multiple de 2. La preuve vaut pour tous les entiers concernés.","Traduire l’hypothèse par une écriture générale.","a,b=__import__('sympy').symbols('a b',integer=True); assert expand((2*a+1)+(2*b+1)-2*(a+b+1))==0"),
E('Contrôler une unité',r"Un élève calcule l’aire d’un rectangle de 3 m sur 40 cm et annonce 120 m$^2$. Corriger.",r"40 cm valent 0,4 m. L’aire vaut $3\times0{,}4=\res{1{,}2\text{ m}^2}$. Le calcul 120 a multiplié des nombres exprimés dans des unités différentes.","Convertir les longueurs avant le produit.","assert 3*Rational(40,100)==Rational('1.2')"),
E('Un arrondi utile',r"Il faut 7,2 L d’un produit vendu en bidons de 3 L. Combien de bidons au minimum ?",r"$7{,}2/3=2{,}4$. Deux bidons n’apportent que 6 L ; trois apportent 9 L. Il faut $\res3$ bidons. L’arrondi à l’entier le plus proche ne couvre pas forcément le besoin.","Interpréter la quantité entière dans le contexte.","assert ceil(Rational('7.2')/3)==3"),
E('Une hypothèse manquante',r"Un triangle est dessiné avec deux côtés de 3 cm et 4 cm. Peut-on affirmer que le troisième vaut 5 cm ?",r"Non : il faudrait savoir que les côtés de 3 et 4 cm sont perpendiculaires pour appliquer Pythagore ainsi. Un triangle de côtés 3, 4, 6 existe aussi car $3+4>6$, et son troisième côté n’est pas 5.","Identifier l’hypothèse nécessaire.","assert 3+4>6 and 3**2+4**2!=6**2"),
E('Un programme constant',r"Choisir x, ajouter 5, doubler, puis retirer deux fois le nombre de départ. Montrer que le résultat est toujours le même.",r"Le résultat est $2(x+5)-2x=2x+10-2x=\res{10}$. Des essais suggèrent ce résultat ; la simplification le prouve pour tout x.","Passer des essais à l’expression générale.","assert expand(2*(x+5)-2*x)==10"),
E('Comparer exactement',r"Sans décimales, comparer $17/24$ et $5/7$.",r"Les dénominateurs sont positifs. $17\times7=119$ et $5\times24=120$, donc $\res{17/24<5/7}$. Un arrondi au dixième aurait masqué la différence.","Conserver une comparaison exacte.","assert 17*7<5*24"),
E('Une conjecture de divisibilité',r"On observe que $n(n+1)$ est pair pour plusieurs entiers n. Le démontrer.",r"Deux entiers consécutifs comprennent toujours un pair : si n est pair, le produit contient ce facteur ; sinon n+1 est pair. Dans les deux cas, $n(n+1)$ est multiple de 2.","Distinguer les deux parités possibles.","assert all((n*(n+1))%2==0 for n in range(-100,101))"),
E('Vérifier une équation',r"Un élève affirme que $x=4$ résout $3(x-2)=x+4$. Vérifier, puis résoudre.",r"Pour 4, les membres valent 6 et 8 : ce n’est pas une solution. $3x-6=x+4$ donne $2x=10$, donc $\res{x=5}$. Le contrôle donne 9 de chaque côté.","Une substitution rapide détecte une erreur.","assert solve(3*(x-2)-(x+4),x)==[5]"),
E('Une moyenne mal interprétée',r"Une classe a une moyenne de 12/20. Est-il certain qu’au moins la moitié des notes sont supérieures ou égales à 12 ?",r"Non. Considérons quatre notes $10;10;10;18$ : leur moyenne vaut 12, mais une seule est au moins 12. La propriété de partage en deux moitiés concerne la médiane, pas la moyenne.","Construire un contre-exemple satisfaisant la donnée.","assert sum([10,10,10,18])/4==12 and sum(v>=12 for v in [10,10,10,18])<2"),
E('Une commande au meilleur prix',r"Pour 24 carnets : A vend à 2,80 € l’unité avec 6 € de livraison ; B vend des lots de 8 à 21 €, livraison gratuite. Comparer les coûts.",r"A coûte $24\times2{,}80+6=\res{73{,}20\text{ €}}$. Il faut trois lots chez B : $\res{63\text{ €}}$. B économise $\res{10{,}20\text{ €}}$. On compare les coûts totaux pour la même quantité.","Inclure conditionnement et frais fixes.","assert 24*Rational('2.8')+6==Rational('73.2') and 3*21==63"),
E('Un modèle de bassin',r"Un bassin pavé de 4 m sur 2,5 m contient 6000 L. La hauteur d’eau maximale est 0,8 m. Calculer la hauteur actuelle puis la quantité encore possible.",r"6000 L valent 6 m$^3$. La base vaut 10 m$^2$, donc la hauteur est $6/10=\res{0{,}6\text{ m}}$. Le volume maximal vaut 8 m$^3$ ; il reste $\res{2000\text{ L}}$.","Relier volume, aire de base et hauteur.","assert 4*Rational('2.5')==10 and Rational(6,10)==Rational('.6') and (8-6)*1000==2000",figure='synthese-bassin'),
E('Un hasard et un budget',r"Une tombola propose 200 billets à 3 €. Vingt billets gagnent chacun un lot coûtant 15 € à l’organisateur. Tous les billets sont vendus et un billet est choisi au hasard par une personne. Calculer la probabilité de gain et le solde de l’organisation, sans autres frais.",r"La probabilité de gain vaut $20/200=\res{1/10}$. Les recettes sont 600 € et les lots coûtent 300 €. Le solde vaut $\res{300\text{ €}}$. Le résultat financier global ne décrit pas la chance d’un billet particulier.","Séparer modèle aléatoire et bilan comptable.","assert Rational(20,200)==Rational(1,10) and 200*3-20*15==300"),
E('Un maximum expliqué',r"Un rectangle a un périmètre de 40 cm. Montrer que son aire vaut $100-(x-10)^2$ si un côté vaut x, puis déterminer la plus grande aire.",r"L’autre côté vaut $20-x$, avec $0<x<20$. L’aire vaut $20x-x^2=100-(x-10)^2$. Un carré étant positif ou nul, l’aire est au plus $\res{100\text{ cm}^2}$. Cette valeur est atteinte pour $x=10$, donc pour un carré.","Transformer l’expression pour lire une borne atteinte.","assert expand(100-(x-10)**2-x*(20-x))==0",figure='rectangle-fonction'),
E('Un plan de révision',r"Une élève réussit 8 automatismes sur 12, puis obtient 9/14 aux problèmes, rédaction comprise. Selon le barème des brevets blancs du livre, quelle note obtient-elle ? Quel travail cibler si ses quatre erreurs concernent les fractions ?",r"Les automatismes rapportent $8\times0{,}5=4$ points. Le total vaut $\res{13/20}$. Reprendre le cours de fractions, refaire les questions ratées sans regarder la solution, puis contrôler sur des exercices nouveaux cible la difficulté identifiée. Ce bilan guide la suite sans résumer toutes les compétences à une note.","Relier le bilan à une action précise.","assert 8*Rational(1,2)+9==13")
],reperes=['Conjecture, preuve et contre-exemple','Hypothèses et contrôle des résultats','Problèmes de synthèse','Méthode et format du brevet 2027'],deco='algorithmique')
